import React, { PropsWithChildren } from 'react';
import { isElement } from 'react-is';

import { ColumnOrderSettings } from './ColumnSettings/ColumnOrderSettings/ColumnOrderSettings.js';
import { _ColumnSettings as ColumnSettings } from './ColumnSettings/ColumnSettings.js';
import { VisibilitySettings } from './ColumnSettings/VisibilitySettings/VisibilitySettings.js';
import { DownloadData } from './DownloadData.js';
import { FontStyle } from './FontStyle.js';
import { LineWrap } from './LineWrap.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
// #region Typings
/**
 * Allowed slots for the DataTableToolbar.
 */
type DataTableToolbarSlots = {
  downloadData: React.ReactElement | null;
  fontStyle: React.ReactElement | null;
  lineWrap: React.ReactElement | null;
};

export type DataTableToolbarProps = PropsWithChildren &
  StylingProps &
  DataTestId;
// #endregion Typings

/**
 * General DataTable toolbar. Adds `props.children` to the toolbar.
 * It is aligned to the end of the line.
 *
 * @param props - contains children.
 * @returns DataTable toolbar containing children.
 */
export const DataTableToolbar = (props: DataTableToolbarProps) => {
  const {
    children,
    style: consumerStyle,
    className: consumerClassName,
    'data-testid': dataTestId,
  } = props;

  const slots: DataTableToolbarSlots = {
    fontStyle: null,
    downloadData: null,
    lineWrap: null,
  };

  const columnSettingsConfig = {
    visibilitySettings: false,
    columnOrderSettings: false,
  };

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case VisibilitySettings:
          columnSettingsConfig.visibilitySettings = true;
          break;
        case ColumnOrderSettings:
          columnSettingsConfig.columnOrderSettings = true;
          break;
        case FontStyle:
          slots.fontStyle = child;
          break;
        case DownloadData:
          slots.downloadData = child;
          break;
        case LineWrap:
          slots.lineWrap = child;
          break;
        default:
          // eslint-disable-next-line no-console
          console.warn(
            'Only VisibilitySettings, ColumnOrderSettings, FontStyle, DownloadData and LineWrap are valid children of the DataTableToolbar.',
          );
      }
    }
  });

  return (
    <Flex
      flexDirection="row"
      justifyContent="flex-end"
      alignItems="flex-end"
      paddingBottom={4}
      paddingLeft={4}
      gap={4}
      data-testid={dataTestId}
      style={{ marginLeft: 'auto', ...consumerStyle }}
      className={consumerClassName}
    >
      <ColumnSettings {...columnSettingsConfig} />
      {slots.fontStyle}
      {slots.lineWrap}
      {slots.downloadData}
    </Flex>
  );
};

DataTableToolbar['displayName'] = 'DataTable.Toolbar';
